import java.util.*

fun main() {
    val scanner = Scanner(System.`in`)
    val k = scanner.nextInt()
    val counts = IntArray(10) // indices 1..9
    for (i in 0 until 4) {
        val line = scanner.next()
        for (c in line) {
            if (c != '.') {
                counts[c - '0']++
            }
        }
    }
    val maxPresses = 2 * k
    for (t in 1..9) {
        if (counts[t] > maxPresses) {
            println("NO")
            return
        }
    }
    println("YES")
}
